//go:build !purego

package sha3

import (
	"crypto/internal/fips140deps/cpu"
	"crypto/internal/impl"
)

// On T-Head cores (XTheadBb, detected from mvendorid), keccakF1600C906 is the
// CRYPTOGAMS no-Zbb round with one-instruction rotates
// (keccak_c906_riscv64.s, generated by gen_keccak_c906.py); elsewhere the
// generic Go permutation.
var useC906 = cpu.RISCV64HasXTheadBb

func init() {
	impl.Register("sha3", "XTheadBb", &useC906)
}

//go:noescape
func keccakF1600C906(a *[200]byte)

func keccakF1600(a *[200]byte) {
	if useC906 {
		keccakF1600C906(a)
	} else {
		keccakF1600Generic(a)
	}
}

func (d *Digest) write(p []byte) (n int, err error) {
	return d.writeGeneric(p)
}
func (d *Digest) read(out []byte) (n int, err error) {
	return d.readGeneric(out)
}
func (d *Digest) sum(b []byte) []byte {
	return d.sumGeneric(b)
}
